import { InferSchemaType, model, Schema } from 'mongoose';

const messageSchema = new Schema(
  {
    conversationId: { type: Schema.Types.ObjectId, ref: 'Conversation', required: true },
    senderId: { type: Schema.Types.ObjectId, ref: 'User', required: true },
    // Generated by the sender; makes retries after a dropped connection idempotent.
    clientMessageId: { type: String, required: true },
    type: { type: String, enum: ['text'], default: 'text', required: true },
    text: { type: String, required: true, maxlength: 2000 }
  },
  { timestamps: { createdAt: true, updatedAt: false } }
);

messageSchema.index({ senderId: 1, clientMessageId: 1 }, { unique: true });
// History pages walk a conversation newest-first by _id.
messageSchema.index({ conversationId: 1, _id: -1 });

export type MessageDocument = InferSchemaType<typeof messageSchema>;
export const Message = model('Message', messageSchema);
